    // 新区路网生长：片区设立后，没有考据年份的支路（cls<=2）按 0/3/6 年分三批铺开；
    // 主干道（cls>=3）与 2000 年就开放的老区不受影响。只有本图启用。
    // legacyRegions：含山 2011 / 2015 是「划归马鞍山」的行政年份，不是修路年份——
    // 县乡道 2000 年前就存在。若沿用片区 open，2000 年后的新增路网会有三分之二挤在含山，
